export type PillVariant = "info" | "success" | "warning";

@Component({
    selector: "app-pill",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<span class="pill" [class]="variant()">{{ label() }}@if (!disableTooltip()) {<span class="hint">i</span>}</span>`
})
export class PillComponent {
    readonly disableTooltip = input(false, { transform: booleanAttribute });
    readonly label = input("");
    readonly variant = input<"info" | "success" | "warning">("info");
}

